"""
gov_logos.py
Logo strip of government bodies / institutions related to this dashboard.
Add more by appending to LOGOS: (name, base64 PNG, optional background colour for
logos with white artwork). Logos are shown for reference/dedication only.
"""

DISCLAIMER = ("Educational project — not an official government publication. Logos are shown "
              "for reference and dedication only and do not imply endorsement.")

LOGOS = [
]


def strip_html(height: int = 46) -> str:
    cells = []
    for name, bg, b64 in LOGOS:
        style = f"height:{height}px;width:auto;display:block;"
        wrap = "display:flex;align-items:center;padding:3px 5px;border-radius:6px;"
        if bg:
            wrap += f"background:{bg};"
        cells.append(
            f'<div title="{name}" style="{wrap}">'
            f'<img alt="{name}" src="data:{"image/jpeg" if b64.startswith("/9j/") else "image/png"};base64,{b64}" style="{style}" /></div>'
        )
    return (
        '<div style="display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:6px 0 2px 0;">'
        + "".join(cells) + "</div>"
    )


