def ministries_html(height: int = 40) -> str:
    """Each federal ministry shown with the Government of Pakistan state emblem
    (the emblem the ministries use) and its name."""
    cells = []
    for n in MINISTRIES:
        _own = MINISTRY_LOGOS.get(n)
        _src = (f"data:{'image/jpeg' if _own.startswith('/9j/') else 'image/png'};base64,{_own}" if _own
                else f"data:{EMBLEM_MIME};base64,{EMBLEM_B64}")
        cells.append(
            '<div style="display:flex;align-items:center;gap:6px;padding:4px 8px;'
            'border:1px solid rgba(128,128,128,.35);border-radius:8px;">'
            f'<img alt="{n}" src="{_src}" '
            f'style="height:{height}px;width:auto;display:block;{"background:"+MINISTRY_BG[n]+";border-radius:4px;padding:2px 4px;" if n in MINISTRY_BG else ""}" />'
            f'<span style="font-size:13px;font-weight:600;line-height:1.2;">{n}</span></div>'
        )
    return '<div style="display:flex;flex-wrap:wrap;gap:8px;margin:4px 0;">' + "".join(cells) + "</div>"


